import{b as e,O as a,g as r,j as o}from"./chunks/framework.DcaUmd3X.js";const y=JSON.parse('{"title":"自动化测试教程","description":"","frontmatter":{},"headers":[],"relativePath":"automation/index.md","filePath":"自动化测试/index.md","lastUpdated":1788565389000}'),i={name:"automation/index.md"};function d(h,t,s,n,l,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="自动化测试教程" tabindex="-1">自动化测试教程 <a class="header-anchor" href="#自动化测试教程" aria-label="Permalink to &quot;自动化测试教程&quot;">​</a></h1><blockquote><p>涵盖 Playwright 端到端测试、pytest + requests 接口测试等主流自动化测试方案的完整教程。</p></blockquote><p>测试平台地址：<a href="https://testing.yychuiyan.com/" target="_blank" rel="noreferrer">https://testing.yychuiyan.com/</a></p><p>playwright-automation源码：<a href="https://github.com/yychuiyan/playwright-automation" target="_blank" rel="noreferrer">https://github.com/yychuiyan/playwright-automation</a></p><p>pytest-automation源码：<a href="https://github.com/yychuiyan/pytest-automation" target="_blank" rel="noreferrer">https://github.com/yychuiyan/pytest-automation</a></p><h2 id="playwright-教程" tabindex="-1">Playwright 教程 <a class="header-anchor" href="#playwright-教程" aria-label="Permalink to &quot;Playwright 教程&quot;">​</a></h2><blockquote><p>从零开始学习微软开源的端到端自动化测试框架——用一套代码同时在 Chromium、Firefox、WebKit 三个浏览器上跑测试。</p></blockquote><p>如果你做过自动化测试，一定遇到过这些问题：</p><ul><li>测试偶尔挂掉，再跑一遍又好了（<strong>flaky 问题</strong>）</li><li>等元素出现要手动写 <code>sleep</code>，时间设短了跑不过、设长了浪费时间</li><li>一个项目要同时兼容 Chrome 和 Safari，要写两套代码</li><li>想截图、录屏、看网络请求，得自己拼接各种第三方工具</li></ul><p>Playwright 的设计初衷就是<strong>解决这些痛点</strong>。它由微软维护，是同一批开发了 Puppeteer 的工程师做的&quot;第二代&quot;产品。</p><blockquote><p><strong>核心思路：Playwright 帮你自动等待一切，让你专注于描述测试行为，而不是处理竞态条件。</strong></p></blockquote><table tabindex="0"><thead><tr><th>篇章</th><th>目标</th><th>内容</th></tr></thead><tbody><tr><td><a href="/automation/playwright/intro/what-is-playwright.html">入门篇</a></td><td>看懂 + 跑通</td><td>Playwright 是什么、安装、第一个测试</td></tr><tr><td><a href="/automation/playwright/writing/locators.html">编写篇</a></td><td>写好测试</td><td>定位器、操作、断言、自动等待、测试组织</td></tr><tr><td><a href="/automation/playwright/tooling/config.html">工具篇</a></td><td>用好工具链</td><td>配置、运行调试、Codegen、Trace、认证管理</td></tr><tr><td><a href="/automation/playwright/engineering/pom.html">工程篇</a></td><td>团队级实践</td><td>POM、Fixture、参数化、API 测试、CI/CD</td></tr><tr><td><a href="/automation/playwright/appendix/commands-ref.html">附录</a></td><td>随查随用</td><td>命令速查、定位器速查、配置项速查、UI 自动化用例规范</td></tr></tbody></table><p>每章末尾都有小结，读完可以直接看小结复习。附录不需要按顺序读，当字典用。</p><h2 id="pytest-requests-教程" tabindex="-1">pytest + requests 教程 <a class="header-anchor" href="#pytest-requests-教程" aria-label="Permalink to &quot;pytest + requests 教程&quot;">​</a></h2><blockquote><p>从零到中高级，用 Python 最流行的测试框架 pytest + requests 搭建接口自动化框架，全程基于 testing-online 实战。</p></blockquote><p>如果你在做接口测试，一定遇到过这些问题：</p><ul><li>登录认证（token/cookie）每个用例都要重复写一遍，改认证方式要改几十处</li><li>同一逻辑的多组测试数据，只能靠复制粘贴或手写循环</li><li>测试一多，想「只跑失败的那些」「跳过某些用例」都做不到</li><li>几百个用例跑完，没有一份像样的报告，只能人肉翻终端输出</li></ul><p>pytest 正是为<strong>解决这些痛点</strong>而生。它最核心的思想是 <strong>fixture 依赖注入</strong>——测试不自己造数据，而是声明「我需要什么」，pytest 负责准备好再喂给它。</p><blockquote><p><strong>核心思路：requests 负责「把请求发出去、把响应拿回来」，pytest 负责「组织用例、准备数据、断言结果」。两者结合就是完整的接口自动化。</strong></p></blockquote><table tabindex="0"><thead><tr><th>篇章</th><th>目标</th><th>内容</th></tr></thead><tbody><tr><td><a href="/automation/pytest/intro/what-is-pytest.html">入门篇</a></td><td>看懂 + 跑通</td><td>pytest 是什么、环境搭建、第一个测试、测试发现与命名、断言</td></tr><tr><td><a href="/automation/pytest/core/fixture-basics.html">核心篇</a></td><td>吃透 pytest 灵魂</td><td>fixture 入门、作用域、清理、进阶、参数化</td></tr><tr><td><a href="/automation/pytest/requests/requests-intro.html">requests 篇</a></td><td>掌握 HTTP 底座</td><td>requests 全套：请求、传参、解析、异常、Session、认证</td></tr><tr><td><a href="/automation/pytest/practice/conftest-structure.html">实战篇</a></td><td>落地真实接口测试</td><td>requests 封装、conftest 结构、登录 fixture、CRUD、参数化、mock</td></tr><tr><td><a href="/automation/pytest/advanced/markers.html">进阶篇</a></td><td>团队级工程能力</td><td>标记与选择、配置、内置 fixture、报告、并行、插件开发</td></tr><tr><td><a href="/automation/pytest/appendix/commands-ref.html">附录</a></td><td>随查随用</td><td>命令速查、fixture 速查、断言速查、常见坑</td></tr></tbody></table><p>每章末尾都有小结，读完可以直接看小结复习。附录当字典用。</p><h2 id="其他工具" tabindex="-1">其他工具 <a class="header-anchor" href="#其他工具" aria-label="Permalink to &quot;其他工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>状态</th></tr></thead><tbody><tr><td>Selenium</td><td>待更新</td></tr><tr><td>Appium</td><td>待更新</td></tr></tbody></table>',23)])])}const m=e(i,[["render",d]]);export{y as __pageData,m as default};
